{
  "references": [
    {
      "id": "R1",
      "summary_ko": "코를 포함한 남자의 얼굴이 알아볼 수 없을 정도로 흐려짐."
    },
    {
      "id": "R2",
      "summary_ko": "사용 중인 빙벽 아이스 도끼가 때때로 곧지 않고 휘어짐."
    },
    {
      "id": "R3",
      "summary_ko": "프롬프트와 달리 등반하는 사람이 아이스 도끼를 사용하지 않음."
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "움직이는 동안 등산 스틱/아이스 도끼 자루가 늘어나고 불규칙하게 휘어지며 부자연스럽게 왜곡됨."
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "R1은 인물의 얼굴 흐림 현상에 관한 것이고, C1은 아이스 도끼 자루의 왜곡 및 휨에 관한 것으로 대상과 결함이 완전히 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "same",
      "reason_ko": "두 설명 모두 사용 중인 아이스 도끼(자루)가 곧지 않고 휘어지거나 왜곡되는 동일한 현상을 다루고 있습니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "R3은 아이스 도끼를 전혀 사용하지 않는다는 내용인 반면, C1은 존재하는 아이스 도끼가 불규칙하게 휘어지고 왜곡된다는 내용으로 결함 유형이 다릅니다."
    }
  ]
}
